param([string]$BaseUrl="http://127.0.0.1:8000",[int]$ProjectId=1)
$ErrorActionPreference="Stop"
function S([string]$scope){Invoke-RestMethod -Method Post -Uri "$BaseUrl/api/v1/auth/local/demo-session" -ContentType "application/json" -Body (@{scope=$scope}|ConvertTo-Json -Compress)}
function P([string]$path,[hashtable]$body,[hashtable]$headers){Invoke-RestMethod -Method Post -Uri "$BaseUrl$path" -Headers $headers -ContentType "application/json" -Body ($body|ConvertTo-Json -Depth 12 -Compress)}
$hq=S hq;$agency=S agency;$client=S client;$hh=@{Authorization="Bearer $($hq.token)"};$ah=@{Authorization="Bearer $($agency.token)"};$ch=@{Authorization="Bearer $($client.token)"};$n=Get-Date -Format "yyyyMMddHHmmssfff";$root="/api/v1/factory-platform/projects/$ProjectId/geo-aeo";$q=P "$root/questions" @{question_reference="BUYER-QUESTION-$n";market="US";locale="en-US"} $hh;$v=P "$root/questions/$($q.id)/answers" @{answer_manifest=@{answer="Source-bound answer";citations=@("FACT-$n")}} $hh;$v=P "$root/answers/$($v.id)/verify" @{expected_revision=$v.revision;reference="GEO-VERIFY-$n"} $ah;$r=P "$root/answers/$($v.id)/releases" @{target="geo-owner";handoff_manifest=@{consumer="geo";automatic_site_publish=$false;ai_appearance_guaranteed=$false}} $hh;$r=P "$root/releases/$($r.id)/approve" @{expected_revision=$r.revision;reference="GEO-APPROVE-$n"} $ah;$r=P "$root/releases/$($r.id)/acknowledge" @{expected_revision=$r.revision;reference="GEO-RECEIPT-$n"} $ch;[pscustomobject]@{question_status=$q.status;answer_status=$v.status;release_status=$r.status;release_available=$r.available;automatic_site_publish=$false;ai_appearance_guaranteed=$false;hq=$hq.user.id;agency=$agency.user.id;consumer=$client.user.id}|ConvertTo-Json
